func (q *Queries) PostureQueueSaasUnowned(ctx context.Context, arg PostureQueueSaasUnownedParams) ([]PostureQueueSaasUnownedRow, error) {
	rows, err := q.db.Query(ctx, postureQueueSaasUnowned,
		arg.OrgID,
		arg.AllAgents,
		arg.AgentIds,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PostureQueueSaasUnownedRow{}
	for rows.Next() {
		var i PostureQueueSaasUnownedRow
		if err := rows.Scan(
			&i.ID,
			&i.AgentID,
			&i.Source,
			&i.FirstSeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

